function fadeToBgm(name,duration=800){if(!bgmFiles[name])return;desiredBgm=name;const outgoing=currentBgmElement;cancelBgmFade();const token=bgmFadeToken;if(!outgoing||outgoing.paused||!bgmEnabled){stopCurrentBgm();startDesiredBgm();return}const started=performance.now(),startVolume=outgoing.volume,timer=setInterval(()=>{if(token!==bgmFadeToken){clearInterval(timer);if(bgmFadeTimer===timer)bgmFadeTimer=null;return}const progress=Math.min(1,(performance.now()-started)/duration);outgoing.volume=Math.max(0,startVolume*(1-progress));if(progress<1)return;clearInterval(timer);if(bgmFadeTimer===timer)bgmFadeTimer=null;outgoing.pause();outgoing.currentTime=0;if(currentBgmElement===outgoing){currentBgmElement=null;currentBgmName=""}startDesiredBgm()},40);bgmFadeTimer=timer}
