function playSeAndWait(name){return new Promise(resolve=>{if(!audioUnlocked||!seEnabled||!seFiles[name]){resolve();return}const path=AUDIO_BASE+seFiles[name],effect=new Audio(path);let settled=false;const finish=()=>{if(settled)return;settled=true;activeSeElements.delete(effect);resolve()};effect.volume=seVolume;effect.preload="auto";effect.addEventListener("ended",finish,{once:true});effect.addEventListener("error",()=>{warnMissingAudio(path);finish()},{once:true});activeSeElements.add(effect);effect.play().catch(()=>{warnMissingAudio(path);finish()});setTimeout(finish,8000)})}
async function startBossIntroSequence(){const sequence=++bossIntroSequence;bossIntroPending=true;desiredBgm="boss";stopCurrentBgm();await playSeAndWait("boss_intro");if(sequence!==bossIntroSequence)return;bossIntroPending=false;if(active&&spawnQueue.some(kind=>["midBoss","armorBoss","mainBoss"].includes(kind)))playBgm("boss");else syncBgmScene()}
function unlockGameAudio(){if(audioUnlocked)return;audioUnlocked=true;startDesiredBgm()}
function syncBgmScene(){if(ended){playBgm("gameover");return}if(!document.querySelector("#library-screen")?.classList.contains("hidden")){playBgm("library");return}if(!document.querySelector("#story-choice")?.classList.contains("hidden")){playBgm("ending");return}if(!ui.modeSelect.classList.contains("hidden")){playBgm("title");return}const bossActive=active&&spawnQueue?.some(kind=>["midBoss","armorBoss","mainBoss"].includes(kind));if(bossActive&&bossIntroPending)return;playBgm(bossActive?"boss":"stage")}
function refreshAudioControls(){const bgmSlider=document.querySelector("#bgm-volume"),seSlider=document.querySelector("#se-volume");if(!bgmSlider||!seSlider)return;const bgmPercent=Math.round(bgmVolume*100),sePercent=Math.round(seVolume*100);bgmSlider.value=bgmPercent;seSlider.value=sePercent;document.querySelector("#bgm-volume-value").textContent=`${bgmPercent}%`;document.querySelector("#se-volume-value").textContent=`${sePercent}%`}
function setBgmVolume(percent){bgmVolume=clampVolume(Number(percent)/100,DEFAULT_BGM_VOLUME);bgmEnabled=bgmVolume>0;if(currentBgmElement)currentBgmElement.volume=bgmVolume;if(bgmEnabled){unlockGameAudio();startDesiredBgm()}saveAudioSettings();refreshAudioControls()}
function setSeVolume(percent){seVolume=clampVolume(Number(percent)/100,DEFAULT_SE_VOLUME);seEnabled=seVolume>0;soundOn=seEnabled;activeSeElements.forEach(effect=>effect.volume=seVolume);saveAudioSettings();refreshAudioControls()}
