function clearGameOverPresentation(nextBgm=""){document.querySelector("#story-continue")?.classList.remove("game-over-scene");document.querySelector("#endless-retry")?.classList.remove("game-over-scene");releaseBackdropArtifacts();if(desiredBgm==="gameover"||currentBgmName==="gameover")stopCurrentBgm();if(nextBgm)playBgm(nextBgm)}
