const gameplayModalSelectors=["#message","#story-continue","#endless-retry","#chapter-reward","#story-choice","#sell-confirm","#research-lab","#research-unlock-event","#mouse-trap-tutorial","#shop-unlock-event","#king-unlock","#chapter-transition","#library-screen","#credits-screen","#audio-settings-screen","#illustration-viewer"];
function releaseBackdropArtifacts(){[document.documentElement,document.body,document.querySelector(".game-screen"),document.querySelector(".field-wrap")].filter(Boolean).forEach(element=>{element.classList.remove("modal-open","overlay-open","backdrop-active","dimmed","is-dimmed");element.style.removeProperty("filter");element.style.removeProperty("backdrop-filter");element.style.removeProperty("brightness")});document.querySelectorAll(".modal-backdrop,.overlay-backdrop,[data-modal-backdrop]").forEach(element=>element.remove());["#story-continue","#endless-retry"].forEach(selector=>{const element=document.querySelector(selector);if(element?.classList.contains("hidden"))element.classList.remove("game-over-scene")})}
function visibleGameplayModals(){return gameplayModalSelectors.map(selector=>document.querySelector(selector)).filter(element=>element&&!element.classList.contains("hidden"))}
function cleanupBackdropIfNoModal(){if(!visibleGameplayModals().length)releaseBackdropArtifacts()}
function clearGameplayModals(except=[]){const keep=new Set(Array.isArray(except)?except:[except]);gameplayModalSelectors.forEach(selector=>{if(!keep.has(selector))document.querySelector(selector)?.classList.add("hidden")});releaseBackdropArtifacts()}
function installModalBackdropGuard(){const elements=gameplayModalSelectors.map(selector=>document.querySelector(selector)).filter(Boolean),observer=new MutationObserver(records=>{for(const record of records){const changed=record.target;if(changed.classList.contains("hidden")){cleanupBackdropIfNoModal();continue}elements.forEach(element=>{if(element!==changed)element.classList.add("hidden")});releaseBackdropArtifacts();return}cleanupBackdropIfNoModal()});elements.forEach(element=>observer.observe(element,{attributes:true,attributeFilter:["class"]}));document.addEventListener("visibilitychange",cleanupBackdropIfNoModal);window.addEventListener("focus",cleanupBackdropIfNoModal)}
