function applyResearchRetryReadOnly(){const lab=document.querySelector("#research-lab"),notice=document.querySelector("#research-retry-notice"),options=document.querySelector("#research-options");lab?.classList.toggle("retry-readonly",endlessRetryActive);notice?.classList.toggle("hidden",!endlessRetryActive);options?.querySelectorAll("button").forEach(button=>{if(endlessRetryActive){if(button.dataset.retryWasDisabled===undefined){button.dataset.retryWasDisabled=button.disabled?"1":"0";button.dataset.retryTitle=button.title||""}button.disabled=true;button.title="リトライ中は研究できません"}else if(button.dataset.retryWasDisabled!==undefined){button.disabled=button.dataset.retryWasDisabled==="1";button.title=button.dataset.retryTitle||"";delete button.dataset.retryWasDisabled;delete button.dataset.retryTitle}})}
function installResearchRetryAccess(){const button=document.querySelector("#research-button"),options=document.querySelector("#research-options");if(!button||!options)return;const syncEntryButton=()=>{if(endlessRetryActive&&button.disabled)button.disabled=false;if(endlessRetryActive&&button.title!=="研究内容を確認できます（リトライ中は研究不可）")button.title="研究内容を確認できます（リトライ中は研究不可）";applyResearchRetryReadOnly()};new MutationObserver(syncEntryButton).observe(button,{attributes:true,attributeFilter:["disabled","title","class"]});new MutationObserver(applyResearchRetryReadOnly).observe(options,{childList:true});syncEntryButton()}
function loadSaveDataVersion(){const version=Number(localStorage.getItem(saveVersionKey));return Number.isInteger(version)&&version>=0?version:0}
function migrateSaveData(){const fromVersion=loadSaveDataVersion();if(fromVersion>SAVE_DATA_VERSION){console.warn("Save data was created by a newer game version",{saveVersion:fromVersion,supportedVersion:SAVE_DATA_VERSION});return false}if(fromVersion===SAVE_DATA_VERSION)return true;switch(fromVersion){case 0:break;default:throw new Error(`Unsupported save migration from version ${fromVersion}`)}localStorage.setItem(saveVersionKey,String(SAVE_DATA_VERSION));console.log("Save data migrated",{fromVersion,toVersion:SAVE_DATA_VERSION});return true}
