function loadMouseEncyclopediaSeen(){if(debugSession)return new Set(mouseEncyclopediaOrder);try{const saved=JSON.parse(localStorage.getItem(mouseEncyclopediaSeenKey)||"[]");return new Set((Array.isArray(saved)?saved:[]).filter(kind=>mouseEncyclopediaData[kind]))}catch{return new Set()}}
