function saveMouseDefeatCounts(counts){if(debugSession)return;const safe={};mouseEncyclopediaOrder.forEach(kind=>safe[kind]=Math.max(0,Math.floor(Number(counts?.[kind])||0)));localStorage.setItem(mouseEncyclopediaKillsKey,JSON.stringify(safe))}
