function registerMouseEncounter(kind){if(!mouseEncyclopediaData[kind])return false;const seen=loadMouseEncyclopediaSeen();if(seen.has(kind))return false;seen.add(kind);saveMouseEncyclopediaSeen(seen);showMouseEncyclopediaNotice(kind);if(!document.querySelector("#mouse-encyclopedia")?.classList.contains("hidden"))renderMouseEncyclopedia(kind);console.log("Mouse encyclopedia registered",{kind,name:enemyTypes[kind]?.name});return true}
