function showMouseEncyclopediaNotice(kind){const data=mouseEncyclopediaData[kind],type=enemyTypes[kind];if(!data||!type)return;clearTimeout(mouseEncyclopediaNoticeTimer);ui.notice.innerHTML=`<b>🐭 ネズミ図鑑に新しく登録されました</b><span>${type.name}</span>`;ui.notice.classList.remove("hidden","library-registered","secret-notice","enemy-growth-dialogue");ui.notice.classList.add("mouse-encyclopedia-notice");mouseEncyclopediaNoticeTimer=setTimeout(()=>{ui.notice.classList.add("hidden");ui.notice.classList.remove("mouse-encyclopedia-notice")},2600)}
function ensureStoryPageUnlocks(){if(localStorage.getItem(storyPageUnlockKey))return;const legacy=loadProgress().storybookPages.map(Number).filter(page=>Number.isInteger(page)&&page>=1&&page<=6).sort((a,b)=>a-b),highestLegacy=legacy.at(-1)||0,contiguous=legacy.length===highestLegacy&&legacy.every((page,index)=>page===index+1),highest=storyCompleted()?6:contiguous&&highestLegacy<6?highestLegacy:0,unlocks={};for(let page=1;page<=6;page++)unlocks[page]=page<=highest;localStorage.setItem(storyPageUnlockKey,JSON.stringify(unlocks));console.log("Story page unlock state initialized",{legacy,highest,unlocks})}
