function loadLegendaryUnlocks(){try{const saved=JSON.parse(localStorage.getItem(legendaryUnlockKey)||"[]");return new Set(Array.isArray(saved)?saved.filter(kind=>persistentLegendTowers.has(kind)):Object.keys(saved).filter(kind=>saved[kind]&&persistentLegendTowers.has(kind)))}catch{return new Set()}}
function saveLegendaryUnlock(kind){if(debugSession||!persistentLegendTowers.has(kind))return;const saved=loadLegendaryUnlocks();saved.add(kind);localStorage.setItem(legendaryUnlockKey,JSON.stringify([...saved]));localStorage.setItem(libraryBooks.special.storage,"true");refreshBookshelf();console.log("Legendary tower saved",{tower:kind,unlocked:[...saved],specialGallery:isLibraryBookUnlocked("special")})}
