function unlockResearchLab(){if(debugSession)return;localStorage.setItem(researchUnlockedKey,"true");if(localStorage.getItem(researchSnacksKey)===null)localStorage.setItem(researchSnacksKey,String(Math.max(0,Math.floor(coins||120))))}
function loadResearch(){const defaults={attack:0,range:0,reward:0,waveReward:0,slots:0,traps:0,secret:0};if(debugSession)return{attack:10,range:5,reward:10,waveReward:5,slots:4,traps:2,secret:2};try{const saved=JSON.parse(localStorage.getItem(researchKey)||"{}");return Object.fromEntries(Object.keys(defaults).map(key=>[key,Math.max(0,Math.floor(Number(saved[key])||0))]))}catch{return defaults}}
