function researchCostFor(key,level){return key==="traps"?[1200,3600][level]||0:key==="slots"?[1000,2500,6000,12000][level]||0:researchCost(level)}
function loadPersistentSnacks(){const saved=localStorage.getItem(researchSnacksKey);return saved===null?120:Math.max(0,Math.floor(Number(saved)||0))}
