function getWave(index){return gameMode==="endless"?endlessWaveConfig(index):storyWaveConfig(index)}
function storyWaveConfig(index){const n=index+1,chapterBalance=storyChapterBalance[chapterForWave(n).number],balance=storyLateWaveBalance[n]||{...chapterBalance,attack:1},baseCount=n<=3?5+n:n<=6?7+Math.floor(n*.8):n<=10?9+Math.floor(n*.9):10+Math.floor(n*1.05);return{count:Math.max(4,baseCount+balance.count),hp:(38+index*23)*balance.hp,speed:0.98+index*.028,reward:8+Math.floor(index*1.5),lifeDamage:balance.attack}}
function endlessHpFactor(waveNumber){const n=Math.max(1,waveNumber),throughThirty=1+Math.min(n,30)*.095+(n>=20?(Math.min(n,30)-20)*.012:0);return n<=30?throughThirty:throughThirty+(n-30)*.092}
function endlessPostKingPressureMultiplier(waveNumber){const n=Math.max(1,waveNumber);if(n<=45)return 1;if(n<=50)return 1+(n-45)*.03;if(n<=55)return 1.15+(n-50)*.05;if(n<=60)return 1.4+(n-55)*.07;return Math.min(2.5,1.75+(n-60)*.03)}
function endlessWaveConfig(index){const n=index+1,density=10+Math.floor(n*1.65)+(n>=10?Math.floor((n-9)*.55):0)+(n>=20?Math.floor((n-19)*.35):0);return{count:Math.min(92,density),hp:52*endlessHpFactor(n)*endlessPostKingPressureMultiplier(n),speed:Math.min(2.75,1.05*(1+n*.011)),reward:Math.max(3,Math.round(3+n*.015))}}
function giantShieldGrowthProfile(waveNumber){if(waveNumber<18)return{stage:"metal",shieldScale:1,speedScale:1};if(waveNumber<=22)return{stage:"wood",shieldScale:.7,speedScale:.85};if(waveNumber<=30)return{stage:"reinforced",shieldScale:.8,speedScale:.9};if(waveNumber<=40)return{stage:"heavy",shieldScale:.9,speedScale:.95};return{stage:"metal",shieldScale:1,speedScale:1}}
