  butterfly.life--;butterfly.phase+=.018;butterfly.x+=butterfly.vx+Math.sin(butterfly.phase*.7)*.06;butterfly.y=butterfly.baseY+Math.sin(butterfly.phase)*16+Math.sin(butterfly.phase*.31)*7;
