function chooseKittenAction(kitten){const actions=["walk","sit","groom","sleep","watchFlowers","watchBirds","visitCats","chaseButterfly"],action=actions[Math.floor(Math.random()*actions.length)];kitten.action=action;kitten.actionUntilFrame=frame+Math.round(randomBetween(160,420));if(action==="visitCats"&&towers.length){const cats=towers.filter(t=>["doro","hima","king","queen","peace"].includes(t.kind)),target=(cats.length?cats:towers)[Math.floor(Math.random()*(cats.length?cats:towers).length)];kitten.targetX=target.x+randomBetween(-50,50);kitten.targetY=target.y+randomBetween(42,70)}else if(action==="chaseButterfly"){const butterfly=ambientCreatures.find(c=>["butterfly","whiteButterfly"].includes(c.kind));kitten.targetX=butterfly?butterfly.x+randomBetween(-35,35):randomBetween(140,1060);kitten.targetY=butterfly?Math.min(700,butterfly.y+120):randomBetween(590,710)}else if(action==="walk"){kitten.targetX=randomBetween(110,1090);kitten.targetY=randomBetween(585,715)}}
