function updateRestingCreature(creature){const restKinds=["butterfly","whiteButterfly","bird"];if(!restKinds.includes(creature.kind))return false;if(creature.action==="rest"){creature.vx=0;creature.phase+=.02;if(frame>=creature.restUntil){creature.action="fly";creature.target=null;creature.direction=Math.random()<.5?1:-1;creature.vx=creature.direction*randomBetween(creature.kind==="bird" ? .6 : .12,creature.kind==="bird" ? .95 : .24);creature.baseY=creature.kind==="bird"?randomBetween(65,205):randomBetween(310,625)}return true}if(!creature.target&&towers.length&&Math.random()<(creature.kind==="bird" ? .0015 : .0035)){creature.target=chooseAmbientTowerTarget(creature.kind)}if(creature.target){const dx=creature.target.x-creature.x,dy=creature.target.y-(creature.y??creature.baseY),d=Math.hypot(dx,dy),speed=creature.kind==="bird" ? .85 : .38;creature.direction=dx>=0?1:-1;if(d<speed+2){creature.x=creature.target.x;creature.y=creature.target.y;creature.baseY=creature.target.y;creature.action="rest";creature.restUntil=frame+Math.round(randomBetween(180,300));creature.vx=0}else{creature.x+=dx/d*speed;creature.y=(creature.y??creature.baseY)+dy/d*speed}return true}return false}
