function storyWaveRoster(index){const n=index+1,w=storyWaveConfig(index),arr=Array(w.count).fill("forest");if(n>=7)for(let i=0;i<Math.floor(w.count*.12);i++)arr[(i*5)%arr.length]="swift";if(n>=16)for(let i=0;i<Math.floor(w.count*.1);i++)arr[(i*7+2)%arr.length]="guard";if([10,15].includes(n))arr.unshift("midBoss");if(n===24)arr.unshift("mainBoss");return arr}
