function enemyReward(kind,baseReward){if(gameMode!=="endless")return Math.ceil(baseReward*(enemyTypes[kind]?.reward||1));if(kind==="golden")return 150+Math.floor(Math.random()*51);const table={forest:.45,swift:.38,guard:.62,endlessSwift:.45,shield:1.08,giantShield:2.25,piper:1.45,trumpet:1.55,violin:1.55,drum:1.75,midBoss:2.6,armorBoss:5.46,mainBoss:6};return Math.max(1,Math.ceil(baseReward*(table[kind]??1)))}
