function queenSlowEffectBonus(t){if(t.kind!=="hima")return 0;return towers.some(source=>source!==t&&source.kind==="queen"&&Math.hypot(source.x-t.x,source.y-t.y)<=baseEffectiveRange(source))?QUEEN_SLOW_EFFECT_BONUS*supportEffectMultiplier():0}
function effectiveRate(t){const speedBonus=Math.max(groomingSpeedBonus(t),catnipActive()?CATNIP_SPEED_BONUS:0)+queenAttackSpeedBonus(t);return t.rate*weather("towerRate")/(1+speedBonus)}
