function signboardBuffForLevel(level=1){const value=Math.max(1,Math.min(10,level));return value===10?.25:.2+(value-1)*.005}
function groomingBuffForLevel(level=1){const value=Math.max(1,Math.min(10,level));return value===10?.4:.3+(value-1)*.01}
function formatSupportPercent(rate){const percent=rate*100;return Number.isInteger(percent)?String(percent):percent.toFixed(1)}
function signboardAttackBonus(t){if(!t.damage)return 0;return towers.filter(source=>source!==t&&source.kind==="sign"&&Math.hypot(source.x-t.x,source.y-t.y)<=baseEffectiveRange(source)).reduce((best,source)=>Math.max(best,signboardBuffForLevel(source.level)*supportEffectMultiplier()),0)}
