function himawariSlowProfile(level=1){const anchors=[{level:1,chance:.15,slow:.2,seconds:2},{level:3,chance:.18,slow:.2,seconds:2.2},{level:5,chance:.22,slow:.25,seconds:2.4},{level:7,chance:.26,slow:.25,seconds:2.7},{level:10,chance:.3,slow:.3,seconds:3}],value=Math.max(1,Math.min(10,level));let low=anchors[0],high=anchors.at(-1);for(let i=1;i<anchors.length;i++)if(value<=anchors[i].level){low=anchors[i-1];high=anchors[i];break}const ratio=(value-low.level)/(high.level-low.level||1),mix=key=>low[key]+(high[key]-low[key])*ratio;return{chance:mix("chance"),multiplier:1-mix("slow"),slow:mix("slow"),frames:Math.round(mix("seconds")*60),seconds:mix("seconds"),radius:types.hima.slowRadius}}
function supportedHimawariSlowProfile(t){const profile={...himawariSlowProfile(t.level)},bonus=queenSlowEffectBonus(t);if(!bonus)return profile;const slow=Math.min(.6,profile.slow*(1+bonus));profile.slow=slow;profile.multiplier=1-slow;profile.frames=Math.round(profile.frames*(1+bonus));profile.seconds=profile.frames/60;return profile}
function starShieldPriority(enemy){return enemy.kind==="giantShield"?3:enemy.kind==="shield"?2:enemy.shieldHp>0?1:0}
function enemyPathProgress(enemy){const enemyPath=enemyRoutePath(enemy),next=enemyPath[enemy.segment+1];if(!next)return enemy.segment;const current=enemyPath[enemy.segment],segmentLength=Math.hypot(next[0]-current[0],next[1]-current[1])||1,distanceToNext=Math.hypot(next[0]-enemy.x,next[1]-enemy.y);return enemy.segment+Math.max(0,Math.min(1,1-distanceToNext/segmentLength))}
function isPeaceReturnCandidate(enemy){return enemy.kind==="forest"&&!enemy.dead&&!enemy.returningHome&&!enemy.returningHomeBoss&&enemy.hp>0&&!enemy.boss&&!enemy.special&&enemy.shieldHp<=0}
function selectPeaceReturnTargets(candidates,count){const healthy=candidates.filter(enemy=>enemy.hp/enemy.maxHp>=.7),pool=healthy.length?healthy:candidates;return pool.sort((a,b)=>enemyPathProgress(b)-enemyPathProgress(a)).slice(0,count)}
function selectTowerTarget(t,targets){if(t.kind!=="star")return targets.sort((a,b)=>enemyPathProgress(b)-enemyPathProgress(a))[0];const shieldTargets=targets.filter(enemy=>starShieldPriority(enemy)>0&&enemy.shieldHp>0);if(shieldTargets.length)return shieldTargets.sort((a,b)=>starShieldPriority(b)-starShieldPriority(a)||b.shieldHp-a.shieldHp||enemyPathProgress(b)-enemyPathProgress(a))[0];return targets.sort((a,b)=>(b.boss?1:0)-(a.boss?1:0)||enemyPathProgress(b)-enemyPathProgress(a))[0]}
function protectingGiantShield(enemy){if(enemy.returningHome)return null;return enemies.find(shield=>shield!==enemy&&!shield.dead&&!shield.returningHome&&shield.kind==="giantShield"&&shield.routeId===enemy.routeId&&shield.shieldHp>0&&shield.segment>=enemy.segment&&shield.segment-enemy.segment<=enemyTypes.giantShield.protectSegments&&Math.hypot(shield.x-enemy.x,shield.y-enemy.y)<=enemyTypes.giantShield.protectRadius)}
function enemyAuraSources(enemy,filter){if(enemy.returningHome)return[];return enemies.filter(aura=>aura!==enemy&&!aura.dead&&!aura.returningHome&&filter(enemyTypes[aura.kind]||{})&&Math.hypot(aura.x-enemy.x,aura.y-enemy.y)<=((enemyTypes[aura.kind]||{}).auraRadius||(enemyTypes[aura.kind]||{}).royalAuraRadius||0))}
function enemyAuraSpeedMultiplier(enemy){let multiplier=isMouseKingMarchWave(wave+1)?0.9:1;enemyAuraSources(enemy,type=>type.enemySpeedAura).forEach(aura=>multiplier*=enemyTypes[aura.kind].enemySpeedAura);return Math.min(1.45,multiplier)}
function enemyAuraDamageMultiplier(enemy){let multiplier=1;enemyAuraSources(enemy,type=>type.damageTakenAura).forEach(aura=>multiplier*=enemyTypes[aura.kind].damageTakenAura);return Math.max(.68,multiplier)}
function applyDrumAura(){enemies.forEach(enemy=>{if(enemy.dead||enemy.drumAuraApplied)return;const source=enemyAuraSources(enemy,type=>type.hpAura)[0];if(!source)return;const bonus=enemyTypes[source.kind].hpAura;enemy.maxHp*=bonus;enemy.hp*=bonus;enemy.drumAuraApplied=true;spawnMarchBuffEffect(enemy,"🥁")})}
function applyDamage(enemy,amount,sourceKind){if(enemy.returningHome&&!enemy.boss)return;if(amount>0)playSe("hit");const starAttack=sourceKind==="star",type=enemyTypes[enemy.kind],armored=!!type.armor,protector=protectingGiantShield(enemy),mitigation=(enemy.damageTaken??1)*(protector?enemyTypes.giantShield.protectedDamageTaken:1)*enemyAuraDamageMultiplier(enemy),baseDamage=amount*mitigation;if(enemy.shieldHp>0){const shieldDamage=baseDamage*(starAttack?types.star.shieldDamageMultiplier:1),bodyLeak=baseDamage*(type.shieldBodyDamage??0.1);enemy.shieldHp=Math.max(0,enemy.shieldHp-shieldDamage);enemy.hp-=bodyLeak;if(starAttack)spawnStarArmorEffect(enemy,true);if(enemy.shieldHp<=0&&!enemy.shieldBroken){enemy.shieldBroken=true;spawnShieldBreakEffect(enemy)}if(starAttack)tryStarFreeze(enemy);return}enemy.hp-=baseDamage*(starAttack&&armored?types.star.armorDamageMultiplier:1);if(starAttack&&armored)spawnStarArmorEffect(enemy,false);if(starAttack)tryStarFreeze(enemy)}
function applyHimawariAreaSlow(center,profile=himawariSlowProfile(1)){
 if(Math.random()>=profile.chance)return;
 const affected=enemies.filter(enemy=>!enemy.dead&&!enemy.returningHome&&enemy.hp>0&&Math.hypot(enemy.x-center.x,enemy.y-center.y)<=profile.radius);
 affected.forEach(enemy=>{enemy.slowMultiplier=Math.min(enemy.slowMultiplier??1,profile.multiplier);enemy.slowUntilFrame=Math.max(enemy.slowUntilFrame||0,frame+profile.frames)});
 addEffectParticle({type:"bloom",x:center.x,y:center.y-8,vx:0,vy:0,life:52,size:profile.radius*.55,color:"#f6cf55"},true);
 addEffectParticle({type:"ring",x:center.x,y:center.y+5,vx:0,vy:0,life:46,size:profile.radius*.72,color:"#f8dc72"},true);
 for(let i=0;i<14;i++){const angle=i/14*Math.PI*2;addEffectParticle({type:"petal",x:center.x+Math.cos(angle)*18,y:center.y-12+Math.sin(angle)*12,vx:Math.cos(angle)*(.65+Math.random()*.45),vy:Math.sin(angle)*.4-.25,life:38+Math.random()*24,size:4+Math.random()*2,color:i%2?"#ffe680":"#f0bd3e",rotation:angle,spin:.05},true)}
}
