function returnDistanceToEntrance(enemy){const enemyPath=enemyRoutePath(enemy),entrance=enemyPath[0];return Math.hypot(enemy.x-entrance[0],enemy.y-entrance[1])}
function returningFacing(enemy){const enemyPath=enemyRoutePath(enemy),target=enemyPath[Math.max(0,enemy.segment-1)]||enemyPath[0];return target[0]>=enemy.x?1:-1}
function spawnReturnHomeVanishEffect(enemy){addEffectParticle({type:"ring",x:enemy.x,y:enemy.y,vx:0,vy:0,life:48,size:30,color:"#fff0bd"},true);addEffectParticle({type:"marchText",text:"ただいま",x:enemy.x,y:enemy.y-42,vx:0,vy:-.16,life:42,size:14,color:"#ffe9a8"},true);for(let i=0;i<7;i++){const angle=i/7*Math.PI*2;addEffectParticle({type:i%2?"spark":"petal",x:enemy.x+Math.cos(angle)*12,y:enemy.y+Math.sin(angle)*8,vx:Math.cos(angle)*.18,vy:-.25+Math.sin(angle)*.08,life:28+Math.random()*12,size:2.2+Math.random()*2,color:i%2?"#ffe9a8":"#f1c86e",rotation:angle,spin:.04},true)}}
function sendEnemyHome(enemy){enemy.returningHome=true;enemy.returnStartFrame=frame;enemy.returnTurnFrame=frame+24;enemy.returnLookUntilFrame=enemy.returnTurnFrame;enemy.returnSpeedScale=.85;enemy.returnFacingX=returningFacing(enemy);enemy.freezeUntilFrame=0;enemy.trapStunUntilFrame=0;enemy.slowUntilFrame=0;addEffectParticle({type:"marchText",text:"？",x:enemy.x,y:enemy.y-62,vx:0,vy:-.12,life:34,size:20,color:"#fff6c7"},true);addEffectParticle({type:"ring",x:enemy.x,y:enemy.y+6,vx:0,vy:0,life:32,size:18,color:"#ffeab0"},true)}
function nudgeBossBack(enemy,t){enemy.returningHomeBoss=true;enemy.returnHomeUntilFrame=Math.max(enemy.returnHomeUntilFrame||0,frame+(t.type.bossRetreatFrames||120));enemy.returnLookUntilFrame=frame+24;enemy.returnSpeedScale=.28;addEffectParticle({type:"marchText",text:"すこしだけ後退",x:enemy.x,y:enemy.y-66,vx:0,vy:-.18,life:56,size:14,color:"#ffe9a3"},true)}
function activatePeaceTower(t){const range=effectiveRange(t),candidates=enemies.filter(enemy=>isPeaceReturnCandidate(enemy)&&Math.hypot(enemy.x-t.x,enemy.y-t.y)<=range),returnTargets=selectPeaceReturnTargets(candidates,t.type.returnHomeCount||3);if(!returnTargets.length)return;spawnPeaceCallEffect(t);playPeaceCallSound();returnTargets.forEach(sendEnemyHome);console.log("Peace tower activated",{returned:returnTargets.length,healthyCandidates:candidates.filter(enemy=>enemy.hp/enemy.maxHp>=.7).length,range:Math.round(range),targets:returnTargets.map(enemy=>({kind:enemy.kind,hpRate:Number((enemy.hp/enemy.maxHp).toFixed(2)),progress:Number(enemyPathProgress(enemy).toFixed(2))}))})}
function tryStarFreeze(enemy){if(frame<(enemy.freezeCooldownUntilFrame||0)||Math.random()>=types.star.freezeChance)return;enemy.freezeUntilFrame=frame+(enemy.boss?types.star.bossFreezeFrames:types.star.freezeFrames);enemy.freezeCooldownUntilFrame=frame+types.star.freezeCooldownFrames;for(let i=0;i<6;i++){const angle=i/6*Math.PI*2;addEffectParticle({type:"star",x:enemy.x+Math.cos(angle)*20,y:enemy.y-18+Math.sin(angle)*15,vx:Math.cos(angle)*.25,vy:-.18,life:34,size:3.5,color:"#eee5ff",rotation:angle,spin:.035},true)}}
function spawnStarArmorEffect(enemy,shieldHit){const count=shieldHit?9:6;for(let i=0;i<count;i++){const angle=i/count*Math.PI*2;addEffectParticle({type:"star",x:enemy.x+Math.cos(angle)*18,y:enemy.y-15+Math.sin(angle)*15,vx:Math.cos(angle)*.65,vy:Math.sin(angle)*.45-.3,life:30+Math.random()*20,size:shieldHit?5:3.8,color:shieldHit?"#fff0a8":"#dcd2ff",rotation:angle,spin:.06},true)}}
function spawnShieldBreakEffect(enemy){addEffectParticle({type:"ring",x:enemy.x,y:enemy.y-12,vx:0,vy:0,life:72,size:46,color:"#bfe8ff"},true);addEffectParticle({type:"shieldBreak",x:enemy.x,y:enemy.y-72,vx:0,vy:-.18,life:70,size:15,color:"#fff0bd"},true);for(let i=0;i<18;i++){const angle=i/18*Math.PI*2;addEffectParticle({type:i%4===0?"star":"spark",x:enemy.x+Math.cos(angle)*22,y:enemy.y-15+Math.sin(angle)*18,vx:Math.cos(angle)*(1.1+Math.random()*1.2),vy:Math.sin(angle)*(1+Math.random())-.6,life:38+Math.random()*26,size:3+Math.random()*2.5,color:i%2?"#d9f0ff":"#d6ad55",rotation:angle,spin:.04},true)}}
function hideBossWaveAlert(){const alert=document.querySelector("#boss-wave-alert");if(!alert)return;alert.classList.add("hidden");alert.classList.remove("play","march")}
function showEndlessBossWaveEvent(waveNumber){
 const march=isMouseKingMarchWave(waveNumber),firstArmor=waveNumber===20,alert=document.querySelector("#boss-wave-alert");
 if(!alert)return;
 try{
  clearTimeout(bossWaveAlertTimer);
  document.querySelector("#boss-wave-label").textContent=march?"SPECIAL BOSS WAVE":"BOSS WAVE";
  document.querySelector("#boss-wave-title").textContent=march?"ネズミ王の大行進！":firstArmor?"鎧ネズミ初登場！":"鎧ボス親衛隊！";
  document.querySelector("#boss-wave-subtitle").textContent=march?"王様ネズミの隊列がやってきます":firstArmor?"まずは一体の特徴を見きわめよう":"盾と笛吹きがボスを守ります";
  alert.classList.remove("hidden","play","march");
  alert.classList.toggle("march",march);
  void alert.offsetWidth;
  alert.classList.add("play");
  bossWaveAlertTimer=setTimeout(hideBossWaveAlert,2600);
  spawnBossWaveParticles(march);
  playBossWaveSound(march);
 }catch(error){
  console.error("Boss wave alert failed",error);
  hideBossWaveAlert();
 }
}
function spawnBossWaveParticles(march=false){const count=march?44:30;for(let i=0;i<count;i++){const angle=i/count*Math.PI*2,ring=i%3===0?185:120;addEffectParticle({type:i%5===0?"star":"spark",x:600+Math.cos(angle)*ring,y:250+Math.sin(angle)*(march?58:42),vx:Math.cos(angle)*.25,vy:-.18-Math.random()*.2,life:64+Math.random()*46,size:2.5+Math.random()*2.8,color:march&&i%4===0?"#ffe39a":"#e7c77a",rotation:angle,spin:.025},true)}}
function playBossWaveSound(){}
function spawnMarchBuffEffect(enemy,label){addEffectParticle({type:"marchText",text:label,x:enemy.x,y:enemy.y-55,vx:0,vy:-.22,life:44,size:17,color:"#ffe5a3"},true)}
function addEffectParticle(p,priority=false){if(particles.length>=360){if(!priority)return;particles.splice(0,Math.min(24,particles.length))}particles.push({...p,maxLife:p.life,rotation:p.rotation||0,spin:p.spin||0})}
function spawnSupportEffect(t){const kind=t.kind;if(kind==="mike"){addEffectParticle({type:"ember",x:t.x,y:t.y-55,vx:0,vy:-.45,life:38,size:12,color:"#f39a42"});for(let i=0;i<5;i++)addEffectParticle({type:"spark",x:t.x+(Math.random()-.5)*18,y:t.y-48,vx:(Math.random()-.5)*.45,vy:-.35-Math.random()*.45,life:25+Math.random()*12,size:2+Math.random()*2,color:"#ffd17a"})}else if(kind==="queen"){addEffectParticle({type:"aura",x:t.x,y:t.y-12,vx:0,vy:0,life:45,size:25,color:"#ffd75c"})}else if(kind==="sign"){addEffectParticle({type:"token",x:t.x,y:t.y-48,vx:(Math.random()-.5)*.25,vy:-.3,life:42,size:7,color:"#e8bd57"})}else if(kind==="groom"){addEffectParticle({type:"aura",x:t.x,y:t.y-12,vx:0,vy:0,life:48,size:22,color:"#f2d27d"});for(let i=0;i<3;i++)addEffectParticle({type:"petal",x:t.x+(Math.random()-.5)*28,y:t.y-35,vx:(Math.random()-.5)*.3,vy:-.2-Math.random()*.2,life:38,size:5,color:"#f4dfab",rotation:Math.random()*Math.PI,spin:.025})}}
function spawnShotTrail(s){const kind=s.kind;if(kind==="doro"||kind==="king")addEffectParticle({type:"spark",x:s.x,y:s.y,vx:(Math.random()-.5)*.25,vy:(Math.random()-.5)*.25,life:16,size:kind==="king"?3.5:2.5,color:kind==="king"?"#f4ce72":"#8bdcff"});else if(kind==="hima")addEffectParticle({type:"petal",x:s.x,y:s.y,vx:(Math.random()-.5)*.35,vy:.1,life:22,size:4.5,color:Math.random()>.5?"#ffd85c":"#fff0a0",rotation:Math.random()*Math.PI,spin:.06});else if(kind==="witch")addEffectParticle({type:"star",x:s.x,y:s.y,vx:(Math.random()-.5)*.25,vy:(Math.random()-.5)*.25,life:18,size:3,color:"#d5a5ff",rotation:Math.random()*Math.PI,spin:.08});else if(kind==="star")addEffectParticle({type:"star",x:s.x,y:s.y,vx:(Math.random()-.5)*.2,vy:-.1,life:24,size:3.5,color:"#eee5ff",rotation:Math.random()*Math.PI,spin:.04})}
function spawnImpactEffect(kind,x,y){const theme={doro:["paw","#7dd8ff"],hima:["bloom","#ffd75a"],witch:["magic","#bd78ff"],king:["paw","#f0c75e"],star:["magic","#ded0ff"]}[kind]||["ring","#fff0b0"],count=kind==="witch"?9:7;addEffectParticle({type:theme[0],x,y,vx:0,vy:0,life:24,size:kind==="king"?22:16,color:theme[1]});for(let i=0;i<count;i++)addEffectParticle({type:kind==="hima"?"petal":"spark",x,y,vx:(Math.random()-.5)*2.2,vy:(Math.random()-.5)*2.2,life:20+Math.random()*12,size:2.5+Math.random()*2.5,color:theme[1],rotation:Math.random()*Math.PI,spin:.07})}
function spawnLevelUpEffect(t){const floral=t.kind==="hima"||t.kind==="queen",paw=t.kind==="doro"||t.kind==="king"||t.kind==="sign"||t.kind==="groom",count=12+Math.min(10,t.level);addEffectParticle({type:floral?"bloom":paw?"paw":"aura",x:t.x,y:t.y-24,vx:0,vy:0,life:88,size:28+t.level*1.5,color:"#f2ca68"},true);addEffectParticle({type:"ring",x:t.x,y:t.y+15,vx:0,vy:0,life:76,size:34+t.level,color:"#ffe49a"},true);for(let i=0;i<count;i++){const angle=i/count*Math.PI*2,radius=28+Math.random()*30,type=floral&&i%2===0?"petal":paw&&i%3===0?"paw":i%4===0?"star":"spark";addEffectParticle({type,x:t.x+Math.cos(angle)*radius,y:t.y-32+Math.sin(angle)*radius*.7,vx:Math.cos(angle)*(.35+Math.random()*.55),vy:-.45-Math.random()*.8,life:52+Math.random()*38,size:type==="petal"?4.5+Math.random()*2:type==="paw"?5+Math.random()*2:2.5+Math.random()*2,color:i%2?"#ffe9a8":"#dca84c",rotation:angle,spin:type==="petal"?.045:.02},true)}}
function spawnGroomingBuffEffect(t){addEffectParticle({type:"paw",x:t.x-12,y:t.y-62,vx:-.08,vy:-.24,life:50,size:6,color:"#fff8dc"});addEffectParticle({type:"paw",x:t.x+13,y:t.y-73,vx:.08,vy:-.2,life:55,size:5,color:"#f6edcf"});for(let i=0;i<4;i++)addEffectParticle({type:"spark",x:t.x+(Math.random()-.5)*34,y:t.y-45-Math.random()*25,vx:(Math.random()-.5)*.22,vy:-.18-Math.random()*.18,life:38+Math.random()*16,size:1.8+Math.random()*1.5,color:"#fff4d1"})}
function spawnMilkUseEffect(){towers.forEach(t=>{if(supportTowerKinds.has(t.kind)||hasSignboardAttackBuff(t)||hasGroomingBuff(t)||hasQueenSupportBuff(t)){addEffectParticle({type:"aura",x:t.x,y:t.y-16,vx:0,vy:0,life:70,size:38,color:"#fff8e6"},true);for(let i=0;i<5;i++)addEffectParticle({type:"spark",x:t.x+(Math.random()-.5)*38,y:t.y-48-Math.random()*18,vx:(Math.random()-.5)*.35,vy:-.2-Math.random()*.25,life:34+Math.random()*18,size:2+Math.random()*2,color:"#fff8e6"},true)}})}
function updateTower(t){if(active&&hasGroomingBuff(t)&&frame%150===t.id%150)spawnGroomingBuffEffect(t);if(t.kind==="mike"||t.kind==="queen"){if(active&&--t.cool<=0){addSnacks(t.kind==="mike"?mikePeriodicSnackAmount(t.level):14+t.level*4,t.kind==="mike"?"mike":"normal");spawnSupportEffect(t);t.cool=t.kind==="mike"?t.type.periodicSnackInterval:220}return}if(t.kind==="peace"){if(active&&--t.cool<=0){activatePeaceTower(t);t.cool=effectiveRate(t)}return}if(t.kind==="sign"||t.kind==="groom"){if(active&&frame%105===t.id%105)spawnSupportEffect(t);return}t.cool-=towerCooldownStep(t);if(t.cool>0)return;const targets=enemies.filter(e=>!e.dead&&!e.returningHome&&Math.hypot(e.x-t.x,e.y-t.y)<=effectiveRange(t));const target=selectTowerTarget(t,targets);if(!target)return;if(t.kind==="witch"){[-.28,0,.28].forEach(a=>shots.push({x:t.x,y:t.y-35,kind:t.kind,spread:true,angle:Math.atan2(target.y-t.y,target.x-t.x)+a,life:45,damage:damageAgainst(t,target),color:t.type.shot}))}else shots.push({x:t.x,y:t.y-35,kind:t.kind,target,damage:damageAgainst(t,target),color:t.type.shot,area:t.kind==="king"?70:0,slowProfile:t.kind==="hima"?supportedHimawariSlowProfile(t):null});t.cool=effectiveRate(t)}
function updateShot(s){if(s.spread){s.x+=Math.cos(s.angle)*7;s.y+=Math.sin(s.angle)*7;s.life--;if(frame%2===0)spawnShotTrail(s);const hit=enemies.find(e=>!e.dead&&!e.returningHome&&Math.hypot(e.x-s.x,e.y-s.y)<e.hitRadius);if(hit){applyDamage(hit,s.damage,s.kind);spawnImpactEffect(s.kind,s.x,s.y);s.dead=true}return}if(!s.target||s.target.dead||s.target.returningHome){s.dead=true;return}const dx=s.target.x-s.x,dy=s.target.y-s.y,d=Math.hypot(dx,dy);if(d<10+s.target.hitRadius*.4){if(s.area)enemies.filter(e=>!e.dead&&!e.returningHome&&Math.hypot(e.x-s.target.x,e.y-s.target.y)<s.area).forEach(enemy=>applyDamage(enemy,s.damage,s.kind));else applyDamage(s.target,s.damage,s.kind);if(s.kind==="hima")applyHimawariAreaSlow(s.target,s.slowProfile);spawnImpactEffect(s.kind,s.target.x,s.target.y);s.dead=true;return}if(frame%2===0)spawnShotTrail(s);s.x+=dx/d*7;s.y+=dy/d*7}
function showEconomyNotice(text,golden=false){const notice=document.querySelector("#economy-notice");if(!notice)return;clearTimeout(economyNoticeTimer);notice.textContent=text;notice.classList.add("hidden");notice.classList.remove("play","golden");void notice.offsetWidth;notice.classList.toggle("golden",golden);notice.classList.remove("hidden");notice.classList.add("play");economyNoticeTimer=setTimeout(()=>notice.classList.add("hidden"),2200)}
function resetEndlessCombo(reason="reset"){if(gameMode==="endless"&&endlessComboKills>0)console.log("Endless combo reset",{reason,kills:endlessComboKills});endlessComboKills=0;endlessComboLastKillFrame=-Infinity}
function resetEconomyRunState(){clearTimeout(economyNoticeTimer);document.querySelector("#economy-notice")?.classList.add("hidden");endlessComboKills=0;endlessComboLastKillFrame=-Infinity;goldenMouseWaves=new Map();catnipCount=0;catnipUntilFrame=0;milkCount=0;milkUntilFrame=0;bossIntroSequence++;bossIntroPending=false}
function registerEndlessComboKill(enemy){if(gameMode!=="endless")return;if(frame-endlessComboLastKillFrame>COMBO_TIMEOUT_FRAMES)endlessComboKills=0;endlessComboKills++;endlessComboLastKillFrame=frame;const reward=COMBO_REWARDS[endlessComboKills];if(!reward)return;addSnacks(reward,"normal");showEconomyNotice(`🔥 ${endlessComboKills}連続撃破！　🍖 +${reward}`);addEffectParticle({type:"rewardText",text:`COMBO +${reward}`,x:enemy.x,y:enemy.y-86,vx:0,vy:-.34,life:72,size:16,color:"#ffe27a"},true);console.log("Endless combo reward",{combo:endlessComboKills,reward,coins})}
