function addSnacks(n,category="normal"){const amount=Math.max(0,Math.floor(n));if(amount>0)playSe("snack");coins+=amount;currentRunAchievements.snacksEarned+=amount;if(runSnackStats)runSnackStats[category==="mike"?"mikeBonus":"normal"]+=amount;savePersistentSnacks();checkRunUnlocks();refreshResearchLabLive();refreshMouseTrapPurchaseUI()}
