function canvasPoint(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*1200/r.width,y:(e.clientY-r.top)*760/r.height}}
function updateHoveredSpot(e){const {x,y}=canvasPoint(e);mouseTrapCursor=mouseTrapMode||mouseTrapTutorialPreview?{x,y}:null;if(mouseTrapMode){hoveredSpot=-1;canvas.style.cursor=isMouseTrapPlacementValid(x,y)?"crosshair":"not-allowed";return}const spotIndex=selectedType&&isUnlocked(selectedType)?nearestSpotIndex(x,y): -1,valid=spotIndex>=0&&!towers.some(t=>t.spot===spotIndex);hoveredSpot=valid?spotIndex:-1;canvas.style.cursor=hoveredSpot>=0?"pointer":selectedType?"crosshair":"default"}
function setupDebugModeUI(){if(!DEBUG_MODE)return;document.querySelector("#debug-mode-button").classList.remove("mode-hidden");document.querySelector(".debug-tools").classList.remove("mode-hidden")}
