function startDebugRun(startAt=selectedDebugWave()){if(!DEBUG_MODE)return false;startAt=Math.max(1,Math.min(100,Number(startAt)||1));debugSession=true;ui.modeSelect.classList.add("hidden");document.querySelector("#debug-panel").classList.add("hidden");reset("endless");wave=Math.max(0,startAt-1);routeBranchActive=false;routeBranchRevealShown=startAt>routeBranchSystem.unlockWave;currentRouteAssignments=[];coins=startAt>=35?45000:99999;lives=999;currentRunAchievements={enemiesDefeated:99999,highestWave:wave,snacksEarned:99999,mainBossDefeated:true};mouseTrapCount=mouseTrapCapacity();catnipCount=CATNIP_CAPACITY;catnipUntilFrame=0;milkCount=startAt>=45?MILK_CAPACITY:0;milkUntilFrame=0;unlockedTowers=new Set(Object.keys(types));storyReplayChapters=new Set(chapters.map(chapter=>chapter.number));document.querySelector("#debug-toolbar").classList.remove("mode-hidden");refreshTowerLocks();refreshBookshelf();showPlacementReason(`DEBUG: Wave ${startAt} の準備状態`);prepareRouteBranchForWave(startAt,{notify:true});captureEndlessCheckpoint();refreshUI();console.log("Debug run started",{startAt,nextWave:wave+1,coins,lives,routeBranchActive,routeBranchRevealShown,routeVisibleDuringPreparation:routeBranchActive,research:loadResearch(),towers:[...unlockedTowers],items:{mouseTrapCount,catnipCount,milkCount}});return true}
function previewDebugCinematic(kind){if(!DEBUG_MODE||!types[kind])return false;if(!debugSession||!ui.modeSelect.classList.contains("hidden"))startDebugRun();playSe("unlock");showLegendaryUnlockCinematic(kind);return true}
function previewDebugAchievement(){if(!DEBUG_MODE)return false;if(!debugSession||!ui.modeSelect.classList.contains("hidden"))startDebugRun();playSe("unlock");clearTimeout(noticeTimer);ui.notice.textContent="✦ 実績解除！ 森の大冒険家 ✦";ui.notice.classList.remove("hidden","library-registered","secret-notice");ui.notice.classList.add("debug-achievement");noticeTimer=setTimeout(()=>ui.notice.classList.add("hidden"),3500);return true}
function openDebugLibrary(){if(!DEBUG_MODE)return false;debugSession=true;refreshBookshelf();openLibrary();return true}
function leaveDebugSession(){debugSession=false;document.querySelector("#debug-toolbar").classList.add("mode-hidden");ui.notice.classList.remove("debug-achievement")}
canvas.addEventListener("mousemove",e=>{updateHoveredSpot(e)});
canvas.addEventListener("mouseleave",()=>{hoveredSpot=-1;mouseTrapCursor=null;canvas.style.cursor=selectedType||mouseTrapMode?"crosshair":"default"});
canvas.addEventListener("pointerdown",closeTowerHint);
canvas.addEventListener("click",e=>{const {x,y}=canvasPoint(e);if(mouseTrapMode){placeMouseTrap(x,y);return}const tower=towers.find(t=>Math.hypot(t.x-x,t.y-y)<45);if(tower){selectedTower=tower;hoveredSpot=-1;showPlacedTowerInfo(tower);console.log("Selected placed tower:",tower.kind,tower.id);refreshUI();return}const hadSelectedTower=!!selectedTower;closeTowerActionMenu(true);const spotIndex=nearestSpotIndex(x,y),maxSlots=towerLimit();console.log("Placement attempt",{placedTowerCount:towers.length,maxTowerSlots:maxSlots,selectedTower:selectedType||"none",clickedBuildSpot:spotIndex>=0?`spot_${spotIndex}`:"none"});if(!selectedType){if(hadSelectedTower)return;console.log("Placement failure reason: no selected tower");showPlacementReason("塔を選んでください。");return}if(!isUnlocked(selectedType)){console.log("Placement failure reason: selected tower locked");showPlacementReason("この塔はまだ使えません。");return}const occupied=spotIndex>=0&&towers.some(t=>t.spot===spotIndex),type=types[selectedType];if(spotIndex<0){console.log("Placement failure reason: invalid build spot");showPlacementReason("配置できる場所を選んでください。");return}if(occupied){console.log("Placement failure reason: spot already occupied");showPlacementReason("ここにはすでに塔があります。");return}if(towers.length>=maxSlots){console.log("Placement failure reason: tower slots full");showPlacementReason("配置上限です。");return}if(towerPlacementLimitReached(selectedType)){console.log("Placement failure reason: tower kind limit reached",{tower:selectedType,limit:towerPlacementLimitByKind(selectedType),current:towers.filter(t=>t.kind===selectedType).length});showPlacementReason(towerPlacementLimitMessage(selectedType));return}if(coins<type.cost){console.log("Placement failure reason: not enough snacks");showPlacementReason("おやつが足りません。");return}coins-=type.cost;towers.push(createTower(selectedType,spotIndex));hoveredSpot=-1;showTowerPlacedFeedback(type.name);console.log("Tower placed",{tower:selectedType,buildSpot:`spot_${spotIndex}`,placedTowerCount:towers.length,maxTowerSlots:towerLimit()});refreshUI()});
canvas.addEventListener("dblclick",e=>{if(mouseTrapMode)return;const {x,y}=canvasPoint(e),tower=towers.find(t=>Math.hypot(t.x-x,t.y-y)<45);if(!tower)return;e.preventDefault();selectedTower=tower;hoveredSpot=-1;showPlacedTowerInfo(tower);tryUpgradeTower(tower)});
