document.addEventListener("keydown",event=>{
 if(event.key!=="Escape")return;
 const illustration=document.querySelector("#illustration-viewer"),audioSettings=document.querySelector("#audio-settings-screen"),credits=document.querySelector("#credits-screen"),library=document.querySelector("#library-screen"),shop=document.querySelector("#shop-panel"),itemTray=document.querySelector("#item-tray"),shopUnlock=document.querySelector("#shop-unlock-event"),research=document.querySelector("#research-lab"),sell=document.querySelector("#sell-confirm"),tutorial=document.querySelector("#mouse-trap-tutorial"),researchUnlock=document.querySelector("#research-unlock-event"),legendary=document.querySelector("#king-unlock"),reward=document.querySelector("#chapter-reward"),storyContinue=document.querySelector("#story-continue"),endlessRetry=document.querySelector("#endless-retry"),storyChoice=document.querySelector("#story-choice"),chapter=document.querySelector("#chapter-transition"),debugPanel=document.querySelector("#debug-panel");
 if(illustration&&!illustration.classList.contains("hidden")){closeIllustrationViewer();return}
 if(audioSettings&&!audioSettings.classList.contains("hidden")){closeAudioSettings();return}
 if(credits&&!credits.classList.contains("hidden")){closeCredits();return}
 if(library&&!library.classList.contains("hidden")){closeLibrary();return}
 if(shop&&!shop.classList.contains("hidden")){closeShop();return}
 if(itemTray&&!itemTray.classList.contains("hidden")){closeItemTray();return}
 if(shopUnlock&&!shopUnlock.classList.contains("hidden")){closeCatnipUnlockEvent();return}
 if(research&&!research.classList.contains("hidden")){closeResearchLab();return}
 if(sell&&!sell.classList.contains("hidden")){closeSellConfirm();return}
 if(tutorial&&!tutorial.classList.contains("hidden")){closeMouseTrapTutorial();return}
 if(researchUnlock&&!researchUnlock.classList.contains("hidden")){closeResearchUnlockEvent(false);return}
 if(legendary&&!legendary.classList.contains("hidden")){closeLegendaryUnlock();return}
 if(reward&&!reward.classList.contains("hidden")){continueAfterChapterReward();return}
 if(storyContinue&&!storyContinue.classList.contains("hidden")){returnToTitleFromContinue();return}
 if(endlessRetry&&!endlessRetry.classList.contains("hidden")){leaveDebugSession();ui.modeSelect.classList.remove("hidden");reset("normal");return}
 if(storyChoice&&!storyChoice.classList.contains("hidden")){leaveDebugSession();ui.modeSelect.classList.remove("hidden");reset("normal");return}
 if(chapter&&!chapter.classList.contains("hidden")){ui.chapter.click();return}
 if(debugPanel&&!debugPanel.classList.contains("hidden")){debugPanel.classList.add("hidden");releaseBackdropArtifacts()}
});
