function isLibraryBookUnlocked(key){return debugSession||key==="drobby"||key==="special"&&loadLegendaryUnlocks().size>0||localStorage.getItem(libraryBooks[key].storage)==="true"}
function isLibraryPageUnlocked(key,page){if(debugSession)return true;if(key==="drobby")return isStoryPageUnlocked(page);if(key==="special"){const legendaryKind=["king","queen","star","peace"][page-1];return !!legendaryKind&&loadLegendaryUnlocks().has(legendaryKind)}return isLibraryBookUnlocked(key)}
function syncSpecialGalleryUnlock(){if(debugSession)return;const legendary=loadLegendaryUnlocks();if(legendary.size>0)localStorage.setItem(libraryBooks.special.storage,"true")}
function unlockLibraryBook(key){const book=libraryBooks[key];if(!book)return;if(!debugSession)localStorage.setItem(book.storage,"true");refreshBookshelf()}
function refreshBookshelf(){document.querySelectorAll(".book-spine[data-book]").forEach(button=>{const key=button.dataset.book,book=libraryBooks[key],unlocked=isLibraryBookUnlocked(key),title=button.querySelector(".book-title"),subtitle=button.querySelector(".book-subtitle"),lock=button.querySelector(".book-lock");button.classList.toggle("locked",!unlocked);button.classList.toggle("available",unlocked);button.setAttribute("aria-disabled",String(!unlocked));title.textContent=unlocked?book.title:"???";subtitle.textContent=unlocked?book.subtitle:"";lock.hidden=unlocked});if(!debugSession)localStorage.setItem(libraryBooks.drobby.storage,"true")}
function closeLibrary(){closeIllustrationViewer();document.querySelector("#mouse-encyclopedia-detail")?.classList.add("hidden");document.querySelector("#library-screen").classList.add("hidden");releaseBackdropArtifacts();syncBgmScene()}
function openLibrary(){clearGameplayModals(["#library-screen"]);closeIllustrationViewer();selectedShelfBook=null;document.querySelectorAll(".book-spine").forEach(book=>book.classList.remove("pulled"));document.querySelector("#library-book-message").textContent="";document.querySelector("#library-screen").classList.remove("hidden");showLibraryBooks();playBgm("library")}
function initializeCredits(){document.querySelector("#credits-version").textContent=GAME_VERSION}
function openAudioSettings(){clearGameplayModals(["#audio-settings-screen"]);refreshAudioControls();refreshEnvironmentEffectsControl();document.querySelector("#audio-settings-screen").classList.remove("hidden")}
function closeAudioSettings(){document.querySelector("#audio-settings-screen")?.classList.add("hidden");releaseBackdropArtifacts()}
function openCredits(){creditsReturnTarget=!document.querySelector("#story-choice").classList.contains("hidden")?"ending":"title";clearGameplayModals(["#credits-screen"]);document.querySelector("#credits-screen").classList.remove("hidden");playBgm(creditsReturnTarget==="ending"?"ending":"title")}
function closeCredits(){document.querySelector("#credits-screen")?.classList.add("hidden");if(creditsReturnTarget==="ending"&&storyCleared){document.querySelector("#story-choice").classList.remove("hidden");playBgm("ending")}else playBgm("title");releaseBackdropArtifacts()}
function showLibraryBookMessage(message){const notice=document.querySelector("#library-book-message");notice.textContent=message;clearTimeout(libraryMessageTimer);libraryMessageTimer=setTimeout(()=>notice.textContent="",2400)}
function handleShelfBook(button){const key=button.dataset.book;if(!isLibraryBookUnlocked(key)){showLibraryBookMessage("まだこの本は見つかっていません。");return}selectedShelfBook=key;document.querySelectorAll(".book-spine").forEach(book=>book.classList.toggle("pulled",book===button));showLibraryBookMessage("本を開いています。");setTimeout(()=>{if(selectedShelfBook===key)openLibraryBook(key)},240)}
function updateStorybookViewport(){const reader=document.querySelector("#storybook-reader"),book=document.querySelector("#storybook-book");if(!reader||!book)return;const mobile=window.matchMedia("(hover: none) and (pointer: coarse)").matches;if(!mobile){reader.classList.remove("mobile-book-fit");book.style.removeProperty("--mobile-book-scale");return}const baseWidth=1600,baseHeight=900,viewportWidth=window.visualViewport?.width||window.innerWidth,viewportHeight=window.visualViewport?.height||window.innerHeight,scale=Math.max(.1,Math.min(viewportWidth/baseWidth,viewportHeight/baseHeight)*.985);reader.classList.add("mobile-book-fit");book.style.setProperty("--mobile-book-scale",String(scale))}
function openLibraryBook(key){playSe("page");currentLibraryBook=key;bookSpread=0;bookTurning=false;document.querySelector("#library-tabs")?.classList.add("hidden");document.querySelector("#mouse-encyclopedia")?.classList.add("hidden");document.querySelector(".bookshelf").classList.add("hidden");document.querySelector("#storybook-reader").classList.remove("hidden");document.querySelector("#storybook-book").classList.remove("turning","turn-forward","turn-backward");updateStorybookViewport();renderBook()}
function availableIllustrationPages(){const book=libraryBooks[currentLibraryBook];return (book.images||[]).map((path,index)=>({page:index+1,path})).filter(item=>item.path&&isLibraryPageUnlocked(currentLibraryBook,item.page))}
function openIllustrationViewer(page){const item=availableIllustrationPages().find(entry=>entry.page===page);if(!item)return;illustrationViewerPage=page;const viewer=document.querySelector("#illustration-viewer"),image=document.querySelector("#illustration-full-image");image.src=item.path;image.alt=`${libraryBooks[currentLibraryBook].title} P${page}`;document.querySelector("#illustration-caption").textContent=`${libraryBooks[currentLibraryBook].title} P${page}`;viewer.classList.remove("hidden");refreshIllustrationControls()}
function closeIllustrationViewer(){document.querySelector("#illustration-viewer")?.classList.add("hidden");illustrationViewerPage=0;cleanupBackdropIfNoModal()}
function moveIllustrationViewer(direction){const pages=availableIllustrationPages(),index=pages.findIndex(item=>item.page===illustrationViewerPage),next=pages[index+direction];if(next)openIllustrationViewer(next.page)}
function refreshIllustrationControls(){const pages=availableIllustrationPages(),index=pages.findIndex(item=>item.page===illustrationViewerPage);document.querySelector("#illustration-prev").disabled=index<=0;document.querySelector("#illustration-next").disabled=index<0||index>=pages.length-1}
function maybeShowMouseTrapTutorial(){if(debugSession||gameMode!=="endless"||localStorage.getItem(mouseTrapTutorialKey)==="true"||!ui.modeSelect.classList.contains("hidden"))return false;document.querySelector("#mouse-trap-tutorial").classList.remove("hidden");document.querySelector("#mouse-trap-button").classList.add("tutorial-glow");console.log("Mouse trap tutorial opened");return true}
function closeMouseTrapTutorial(){const tutorial=document.querySelector("#mouse-trap-tutorial");if(tutorial.classList.contains("hidden"))return;localStorage.setItem(mouseTrapTutorialKey,"true");tutorial.classList.add("hidden");mouseTrapTutorialPreview=true;mouseTrapCursor={x:path[Math.floor(path.length/2)][0],y:path[Math.floor(path.length/2)][1]};document.querySelector("#mouse-trap-button").classList.add("tutorial-glow");clearTimeout(mouseTrapTutorialTimer);mouseTrapTutorialTimer=setTimeout(()=>{mouseTrapTutorialPreview=false;mouseTrapCursor=null;document.querySelector("#mouse-trap-button").classList.remove("tutorial-glow")},3600);console.log("Mouse trap tutorial closed; range preview shown");cleanupBackdropIfNoModal();refreshUI()}
function showMouseTrapHelp(){if(gameMode!=="endless")return;clearTimeout(mouseTrapHelpTimer);document.querySelector("#mouse-trap-help").classList.remove("hidden")}
function hideMouseTrapHelp(){clearTimeout(mouseTrapHelpTimer);document.querySelector("#mouse-trap-help").classList.add("hidden")}
function maybeShowResearchUnlockEvent(){if(debugSession||gameMode!=="endless"||!isResearchUnlocked()||localStorage.getItem(researchIntroSeenKey)==="true"||researchUnlockEventOpen)return false;researchUnlockEventOpen=true;researchPaused=true;document.querySelector("#research-unlock-event").classList.remove("hidden");console.log("Research Lab unlock event opened",{wave});refreshUI();return true}
function closeResearchUnlockEvent(openLab=false){if(!researchUnlockEventOpen)return;researchUnlockEventOpen=false;researchPaused=false;localStorage.setItem(researchIntroSeenKey,"true");document.querySelector("#research-unlock-event").classList.add("hidden");console.log("Research Lab unlock event closed",{openLab});cleanupBackdropIfNoModal();refreshUI();if(openLab)openResearchLab()}
function openResearchLab(){if(!isResearchUnlocked())return;localStorage.setItem(researchOpenedKey,"true");localStorage.setItem(researchIntroSeenKey,"true");renderResearchLab();applyResearchRetryReadOnly();document.querySelector("#research-lab").classList.remove("hidden");refreshUI()}
function closeResearchLab(){document.querySelector("#research-lab").classList.add("hidden");cleanupBackdropIfNoModal()}
function showResearchComplete(text){const notice=document.querySelector("#research-complete");notice.textContent=`✦ ${text} 完了 ✦`;notice.classList.remove("hidden","play");void notice.offsetWidth;notice.classList.add("play");clearTimeout(researchNoticeTimer);researchNoticeTimer=setTimeout(()=>notice.classList.add("hidden"),1300)}
function buyResearch(key){if(endlessRetryActive)return;const levels=loadResearch(),definition=researchDefinitions[key];if(!definition||levels[key]>=definition.max)return;const cost=researchCostFor(key,levels[key]);if(coins<cost)return;coins-=cost;levels[key]++;saveResearch(levels);if(key==="traps"&&gameMode==="endless")mouseTrapCount=Math.min(mouseTrapCapacity(),mouseTrapCount+1);savePersistentSnacks();showResearchComplete(definition.name);console.log("Research completed",{research:key,level:levels[key],cost,remainingSnacks:coins});renderResearchLab();refreshUI()}
function buySecretResearch(){if(endlessRetryActive)return;const levels=loadResearch(),total=standardResearchTotal(levels),level=levels.secret||0,cost=[3200,12800][level],required=[15,25][level];if(level>=2||total<required||coins<cost)return;const kind=level===0?"king":"queen";coins-=cost;levels.secret=level+1;saveResearch(levels);savePersistentSnacks();showResearchComplete(kind==="king"?"森の王様ドロビー研究":"ひまわり女王研究");console.log("Secret research completed",{tower:kind,level:levels.secret,totalResearch:total,waveRequirement:legendaryWaveRequirement(kind),highestWave:highestEndlessWaveReached(),available:isLegendaryTowerAvailable(kind)});if(isLegendaryTowerAvailable(kind))unlockTower(kind);renderResearchLab();refreshUI()}
function refreshResearchLabLive(){const lab=document.querySelector("#research-lab");if(!lab||lab.classList.contains("hidden"))return;document.querySelector("#research-snacks").textContent=coins;if(endlessRetryActive){applyResearchRetryReadOnly();return}const levels=loadResearch();document.querySelectorAll("#research-options [data-research]").forEach(button=>{const key=button.dataset.research,definition=researchDefinitions[key],level=Math.min(levels[key]||0,definition.max),maxed=level>=definition.max,cost=maxed?0:researchCostFor(key,level);button.disabled=maxed||coins<cost;button.textContent=maxed?"研究完了":`研究する　🍖${cost}`});const secretButton=document.querySelector("#research-options [data-secret-research]");if(secretButton){const level=Math.min(levels.secret||0,2),total=standardResearchTotal(levels),required=[15,25][level],cost=[3200,12800][level],ready=total>=required;secretButton.disabled=!ready||coins<cost;secretButton.textContent=ready?`研究する　🍖${cost}`:`研究Lv ${required}で解禁`}const starButton=document.querySelector("#research-options [data-star-research]");if(starButton){const complete=starResearchComplete(),unlocked=isLegendaryTowerAvailable("star");starButton.disabled=complete||coins<STAR_RESEARCH_COST;starButton.textContent=unlocked?"使用可能":complete?"研究完了":`スター研究　🍖${STAR_RESEARCH_COST}`}const peaceButton=document.querySelector("#research-options [data-peace-research]");if(peaceButton){const complete=peaceResearchComplete(),unlocked=isLegendaryTowerAvailable("peace");peaceButton.disabled=complete||coins<PEACE_RESEARCH_COST;peaceButton.textContent=unlocked?"使用可能":complete?"研究完了":`ふたりの研究　🍖${PEACE_RESEARCH_COST}`}applyResearchRetryReadOnly()}
function renderResearchLab(){const levels=loadResearch(),standardTotal=standardResearchTotal(levels),total=standardTotal+levels.secret,options=document.querySelector("#research-options");document.querySelector("#research-snacks").textContent=coins;document.querySelector("#research-total").textContent=total;document.querySelector("#tower-slots").textContent=towerLimit();options.innerHTML=Object.entries(researchDefinitions).map(([key,definition])=>{const level=Math.min(levels[key],definition.max),maxed=level>=definition.max,cost=maxed?0:researchCostFor(key,level),next=key==="traps"&&!maxed?`<br>次：最大${4+level}個`:key==="waveReward"&&!maxed?`<br>次：エンドレスWave報酬 +${(level+1)*5}%`:key==="slots"&&!maxed?`<br>次：配置上限 ${towerSlotsForResearchLevel(level+1)}基`:"";return `<article class="research-option"><strong>${definition.name}</strong><span>Lv ${level} / ${definition.max}　${definition.effect}<br>${researchEffectText(key,level)}${next}</span><button data-research="${key}" ${maxed||coins<cost?"disabled":""}>${maxed?"研究完了":`研究する　🍖${cost}`}</button></article>`}).join("")+renderSecretResearch(levels,standardTotal);options.querySelectorAll("[data-research]").forEach(button=>button.onclick=()=>buyResearch(button.dataset.research));options.querySelector("[data-secret-research]")?.addEventListener("click",buySecretResearch)}
function renderSecretResearch(levels,total){const level=Math.min(levels.secret||0,2),highest=highestEndlessWaveReached();let html;if(level>=2)html=`<article class="research-option legendary"><strong>隠しキャラ研究</strong><span>Lv 2 / 2　研究完了<br>森の王様：${isLegendaryTowerAvailable("king")?"使用可能":`Wave40 ${Math.min(40,highest)} / 40`}<br>ひまわり女王：${isLegendaryTowerAvailable("queen")?"使用可能":`Wave60 ${Math.min(60,highest)} / 60`}</span><button disabled>研究完了</button></article>`;else{const required=[15,25][level],cost=[3200,12800][level],ready=total>=required,subject=level===0?"森の王様ドロビー":"ひまわり女王",waveNeed=level===0?40:60;html=`<article class="research-option legendary"><strong>隠しキャラ研究</strong><span>Lv ${level} / 2　次の研究：${subject}<br>通常研究合計Lv ${required}が必要（現在${total}）<br>使用条件：研究 AND Wave${waveNeed}</span><button data-secret-research ${!ready||coins<cost?"disabled":""}>${ready?`研究する　🍖${cost}`:`研究Lv ${required}で解禁`}</button></article>`}return html+renderStarResearch()}
function renderStarResearch(){const progress=starUnlockProgress(),unlocked=isLegendaryTowerAvailable("star"),waveText=progress.wave>=80?"✓":`${Math.min(progress.wave,80)} / 80`,killText=progress.shieldKills>=50?"✓":`${Math.min(progress.shieldKills,50)} / 50`,peace=peaceUnlockProgress(),peaceUnlocked=isLegendaryTowerAvailable("peace"),peaceWaveText=peace.wave>=100?"✓":`${Math.min(peace.wave,100)} / 100`;return `<article class="research-option legendary star-research"><strong>⭐ スター塔</strong><span class="star-progress">研究　${progress.research?"✓":"未完了"}<br>Wave80　${waveText}<br>巨大盾撃破　${killText}</span><button data-star-research ${progress.research||coins<STAR_RESEARCH_COST?"disabled":""}>${unlocked?"使用可能":progress.research?"研究完了":`スター研究　🍖${STAR_RESEARCH_COST}`}</button></article><article class="research-option legendary peace-research"><strong>🌿 ドロビー＆ひまわり</strong><span class="star-progress">研究　${peace.research?"✓":"未完了"}<br>Wave100　${peaceWaveText}<br>最後の平和支援塔</span><button data-peace-research ${peace.research||coins<PEACE_RESEARCH_COST?"disabled":""}>${peaceUnlocked?"使用可能":peace.research?"研究完了":`ふたりの研究　🍖${PEACE_RESEARCH_COST}`}</button></article>`}
function buyStarResearch(){if(endlessRetryActive||starResearchComplete()||coins<STAR_RESEARCH_COST)return;coins-=STAR_RESEARCH_COST;localStorage.setItem(starResearchKey,"true");savePersistentSnacks();showResearchComplete("スター研究");renderResearchLab();refreshUI();checkStarUnlock()}
function buyPeaceResearch(){if(endlessRetryActive||peaceResearchComplete()||coins<PEACE_RESEARCH_COST)return;coins-=PEACE_RESEARCH_COST;localStorage.setItem(peaceResearchKey,"true");savePersistentSnacks();showResearchComplete("ふたりの研究");renderResearchLab();refreshUI();checkPeaceUnlock()}
