function playBookshelfSound(){if(!soundOn)return;const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return;audio=audio||new AudioContext();const now=audio.currentTime,oscillator=audio.createOscillator(),gain=audio.createGain(),noise=audio.createBuffer(1,Math.floor(audio.sampleRate*.16),audio.sampleRate),noiseData=noise.getChannelData(0);for(let i=0;i<noiseData.length;i++)noiseData[i]=(Math.random()*2-1)*(1-i/noiseData.length);const source=audio.createBufferSource(),filter=audio.createBiquadFilter(),noiseGain=audio.createGain();oscillator.type="sine";oscillator.frequency.setValueAtTime(105,now);oscillator.frequency.exponentialRampToValueAtTime(66,now+.18);gain.gain.setValueAtTime(scaledSeGain(.06),now);gain.gain.exponentialRampToValueAtTime(.001,now+.22);source.buffer=noise;filter.type="lowpass";filter.frequency.value=520;noiseGain.gain.setValueAtTime(scaledSeGain(.035),now);noiseGain.gain.exponentialRampToValueAtTime(.001,now+.16);oscillator.connect(gain).connect(audio.destination);source.connect(filter).connect(noiseGain).connect(audio.destination);oscillator.start(now);oscillator.stop(now+.23);source.start(now)}
