function mouseImageMarkup(kind,seen,big=false){const type=enemyTypes[kind],data=mouseEncyclopediaData[kind],src=type&&imageFiles[type.sprite]?`assets/${imageFiles[type.sprite]}`:"";const fallback=seen?data.icon:"?";return `<span class="${big?"mouse-detail-fallback-layer":"mouse-card-fallback"}">${fallback}</span>${src&&seen?`<img src="${src}" alt="${type.name}" loading="lazy" onerror="this.hidden=true">`:""}`}
function renderMouseEncyclopedia(selectedKind=""){const grid=document.querySelector("#mouse-encyclopedia-grid");if(!grid)return;const seen=loadMouseEncyclopediaSeen(),counts=loadMouseDefeatCounts();grid.innerHTML=mouseEncyclopediaOrder.filter(kind=>enemyTypes[kind]&&mouseEncyclopediaData[kind]).map(kind=>{const unlocked=seen.has(kind),type=enemyTypes[kind],data=mouseEncyclopediaData[kind];return `<button class="mouse-card ${unlocked?"unlocked":"locked"}" type="button" data-mouse="${kind}" aria-label="${unlocked?type.name:"未遭遇のネズミ"}"><span class="mouse-card-art">${mouseImageMarkup(kind,unlocked)}</span><strong>${unlocked?type.name:"???"}</strong><small>${unlocked?`${data.icon} ${data.category}`:"🔒 未遭遇"}</small>${unlocked?`<em>撃破 ${counts[kind]||0}</em>`:""}</button>`}).join("");grid.querySelectorAll("[data-mouse]").forEach(button=>button.onclick=()=>openMouseEncyclopediaDetail(button.dataset.mouse));if(selectedKind)openMouseEncyclopediaDetail(selectedKind)}
function openMouseEncyclopediaDetail(kind){const detail=document.querySelector("#mouse-encyclopedia-detail"),type=enemyTypes[kind],data=mouseEncyclopediaData[kind];if(!detail||!type||!data)return;const seen=isMouseEncyclopediaSeen(kind),counts=loadMouseDefeatCounts();document.querySelectorAll(".mouse-card").forEach(card=>card.classList.toggle("selected",card.dataset.mouse===kind));document.querySelector("#mouse-detail-category").textContent=seen?`${data.icon} ${data.category}`:"🔒 未遭遇";document.querySelector("#mouse-detail-name").textContent=seen?type.name:"???";document.querySelector("#mouse-detail-lore").textContent=seen?data.lore:"まだ図鑑に記録されていません。ゲーム中で出会うと内容が開きます。";document.querySelector("#mouse-detail-feature").textContent=seen?data.feature:"???";document.querySelector("#mouse-detail-ability").textContent=seen?data.ability:"未遭遇のため非表示";document.querySelector("#mouse-detail-counter").textContent=seen?data.counter:"未遭遇のため非表示";document.querySelector("#mouse-detail-seen").textContent=seen?"遭遇済み":"未遭遇";document.querySelector("#mouse-detail-kills").textContent=seen?`${counts[kind]||0}体`:"-";const image=document.querySelector("#mouse-detail-image"),fallback=document.querySelector("#mouse-detail-fallback");image.hidden=true;image.removeAttribute("src");fallback.textContent=seen?data.icon:"?";if(seen&&imageFiles[type.sprite]){image.src=`assets/${imageFiles[type.sprite]}`;image.alt=type.name;image.hidden=false;image.onerror=()=>{image.hidden=true}}detail.classList.remove("hidden")}
function maxBookSpread(){return Math.max(0,Math.ceil(libraryBooks[currentLibraryBook].pages.length/2)-1)}
function turnBook(direction){const next=Math.max(0,Math.min(maxBookSpread(),bookSpread+direction));if(bookTurning||next===bookSpread)return;bookTurning=true;const book=document.querySelector("#storybook-book");book.classList.add("turning",direction>0?"turn-forward":"turn-backward");playPageTurnSound();setTimeout(()=>{bookSpread=next;renderBook()},210);setTimeout(()=>{book.classList.remove("turning","turn-forward","turn-backward");bookTurning=false},450)}
function renderBook(){const book=libraryBooks[currentLibraryBook],pageNumbers=[bookSpread*2+1,bookSpread*2+2];["left","right"].forEach((side,i)=>{const page=pageNumbers[i],exists=page<=book.pages.length,open=exists&&isLibraryPageUnlocked(currentLibraryBook,page),imagePath=open?book.images?.[page-1]:null,article=document.querySelector(`.book-page.${side}`),image=document.querySelector(`#${side}-page-image`),text=document.querySelector(`#${side}-page-text`),pageNo=document.querySelector(`#${side}-page-no`),pageText=book.pages[page-1];article.classList.toggle("locked",exists&&!open);article.classList.toggle("empty-page",!exists);pageNo.textContent=exists?`P${page}`:"";text.textContent=!exists?"":!open?"まだ見つかっていません":pageText||"物語のつづきは、まだ白い頁の中で眠っています。";if(imagePath){image.src=imagePath;image.alt=`${book.title} P${page}`;image.dataset.page=String(page);image.tabIndex=0;image.setAttribute("role","button");image.setAttribute("aria-label",`${book.title} P${page}を拡大表示`);image.hidden=false}else{image.hidden=true;image.removeAttribute("src");image.removeAttribute("data-page");image.removeAttribute("tabindex");image.removeAttribute("role");image.removeAttribute("aria-label");image.alt=""}});const visibleEnd=Math.min(pageNumbers[1],book.pages.length);document.querySelector("#book-page-indicator").textContent=`${pageNumbers[0]} - ${visibleEnd} / ${book.pages.length}`;document.querySelector("#prev-pages").disabled=bookSpread===0;document.querySelector("#next-pages").disabled=bookSpread>=maxBookSpread()}
function fitMobileLandscape(){const screen=document.querySelector(".game-screen"),mobile=window.matchMedia("(orientation: landscape) and (hover: none) and (pointer: coarse)").matches;if(!mobile){["position","left","top","width","height","transform","transformOrigin"].forEach(property=>screen.style[property]="");return}const viewport=window.visualViewport,width=Math.max(1,Math.round(viewport?.width||window.innerWidth)),height=Math.max(1,Math.round(viewport?.height||window.innerHeight)),scale=Math.min(1,width/1024,height/560);screen.style.position="fixed";screen.style.left=`${Math.round(viewport?.offsetLeft||0)}px`;screen.style.top=`${Math.round(viewport?.offsetTop||0)}px`;screen.style.width=`${width/scale}px`;screen.style.height=`${height/scale}px`;screen.style.transformOrigin="top left";screen.style.transform=`scale(${scale})`;document.documentElement.style.setProperty("--mobile-game-scale",String(scale))}
function optionalStartup(label,fn){try{return fn()}catch(error){console.error(`${label} startup step failed; continuing without it.`,error);return null}}
function loop(){try{if(!ui.modeSelect.classList.contains("hidden")){setTimeout(loop,250);return}for(let step=0;step<gameSpeed;step++)update();draw()}catch(error){console.error("Game loop error",error);active=false;ended=true;releaseBackdropArtifacts();ui.modeSelect.classList.remove("hidden");return}requestAnimationFrame(loop)}
function bootGame(){if(gameLoopRunning)return;gameLoopRunning=true;window.addEventListener("resize",fitMobileLandscape,{passive:true});window.addEventListener("orientationchange",()=>setTimeout(fitMobileLandscape,120),{passive:true});window.visualViewport?.addEventListener("resize",fitMobileLandscape,{passive:true});window.addEventListener("pageshow",releaseBackdropArtifacts);migrateSaveData();loadAudioSettings();loadEnvironmentEffectsSetting();optionalStartup("Audio controls",()=>{refreshAudioControls();refreshEnvironmentEffectsControl()});optionalStartup("Credits",initializeCredits);optionalStartup("Story pages",ensureStoryPageUnlocks);optionalStartup("Special gallery",syncSpecialGalleryUnlock);optionalStartup("Shop unlock state",ensureCatnipUnlockState);if(storyCompleted())document.querySelector('[data-mode="endless"]')?.classList.remove("mode-hidden");optionalStartup("Debug UI",setupDebugModeUI);if(!STARTUP_RECOVERY_MODE){optionalStartup("Modal guard",installModalBackdropGuard);optionalStartup("Research scroll",installResearchScrollMemory);optionalStartup("Research retry access",installResearchRetryAccess)}optionalStartup("Mobile layout",fitMobileLandscape);reset("normal");syncBgmScene();document.body.classList.remove("booting");loop()}
